using Quill.Windows;
using Xunit;
namespace Quill.Windows.Tests;
public sealed class TestFolder : IDisposable {
 public string Path { get; } = System.IO.Path.Combine(System.IO.Path.GetTempPath(),"Quill.NativeV2.Tests",Guid.NewGuid().ToString("N"));
 public TestFolder() => Directory.CreateDirectory(Path);
 public void Dispose() { if (Directory.Exists(Path)) Directory.Delete(Path,true); }
}
public sealed class StorageTests {
 [Fact] public void CleanupAutomaticTransitionsSnapshotEffectiveSelectionAndEnableCleanup() { using var f = new TestFolder(); var store = new SettingsStore(f.Path); store.SetProvider(Provider.Gemini); store.SetCleanupAutomatic(false); Assert.False(store.Value.CleanupAutomatic); Assert.Equal(Provider.Gemini,store.Value.CleanupProvider); Assert.Equal("gemini-3.5-flash-lite",store.Value.CleanupModel); store.SetCleanupEnabled(false); store.SetCleanupAutomatic(true); Assert.True(store.Value.UseCleanup); Assert.True(store.Value.CleanupEnabled); }
 [Fact] public void DeliberateCleanupOnOptsIntoManualPaidProvider() { using var f = new TestFolder(); var store = new SettingsStore(f.Path); store.SetProvider(Provider.OpenAI); Assert.False(store.Value.UseCleanup); store.SetCleanupEnabled(true); Assert.False(store.Value.CleanupAutomatic); Assert.True(store.Value.UseCleanup); Assert.Equal(Provider.OpenAI,store.Value.CleanupProvider); Assert.Equal("gpt-4o-mini",store.Value.CleanupModel); }
 [Fact] public void CleanupModelMemorySurvivesSwitchesAndRelaunch() { using var f = new TestFolder(); var store = new SettingsStore(f.Path); store.SetCleanupModel("chosen-groq"); store.SetCleanupProvider(Provider.OpenAI); store.SetCleanupModel("chosen-openai"); store.SetCleanupProvider(Provider.Groq); Assert.Equal("chosen-groq",store.Value.CleanupModel); store = new SettingsStore(f.Path); store.SetCleanupProvider(Provider.OpenAI); Assert.Equal("chosen-openai",store.Value.CleanupModel); }
 [Fact] public void ManualModelSelectionCapturesAutomaticProviderAndSpeechSwitchResetsDefault() { using var f = new TestFolder(); var store = new SettingsStore(f.Path); store.SetProvider(Provider.Gemini); store.SetCleanupModel("manual-gemini"); Assert.False(store.Value.CleanupAutomatic); Assert.Equal(Provider.Gemini,store.Value.CleanupProvider); store.Value.CustomModel = "my-custom"; store.SetProvider(Provider.Custom); Assert.Equal("my-custom",store.Value.SpeechModel); store.SetProvider(Provider.Groq); Assert.Equal("whisper-large-v3-turbo",store.Value.SpeechModel); }
 [Fact] public void CustomKeysAreBoundToExactNormalizedEndpoint() { using var f = new TestFolder(); var store = new SecretStore(f.Path); store.Add(Provider.Custom,"server-a-secret","A","https://server.example/v1/"); Assert.Equal("server-a-secret",store.Read(Provider.Custom,"https://server.example/v1")); Assert.Null(store.Read(Provider.Custom,"https://different.example/v1")); Assert.Null(store.Read(Provider.Custom,"https://server.example/v2")); Assert.Null(store.Read(Provider.Custom)); store.Add(Provider.Custom,"server-b-secret","B","https://different.example/v1"); Assert.Equal("server-a-secret",store.Read(Provider.Custom,"https://server.example/v1")); Assert.Equal("server-b-secret",store.Read(Provider.Custom,"https://different.example/v1")); Assert.Single(store.List(Provider.Custom,"https://server.example/v1")); Assert.Throws<ArgumentException>(() => store.Activate(Provider.Custom,store.ActiveId(Provider.Custom,"https://server.example/v1")!,"https://different.example/v1")); Assert.Equal("server-a-secret",new SecretStore(f.Path).Read(Provider.Custom,"https://server.example/v1")); }
 [Fact] public void SecretsAreDpapiEncryptedAndProviderIsolated() { using var f = new TestFolder(); var store = new SecretStore(f.Path); store.Add(Provider.Groq,"test-provider-secret-first","First"); store.Add(Provider.OpenAI,"test-provider-secret-second","Second"); Assert.Equal("test-provider-secret-first",store.Read(Provider.Groq)); Assert.Equal("test-provider-secret-second",new SecretStore(f.Path).Read(Provider.OpenAI)); var data = File.ReadAllText(System.IO.Path.Combine(f.Path,"keys.dpapi.json")); Assert.DoesNotContain("test-provider-secret",data); Assert.Null(store.Read(Provider.Gemini)); }
 [Fact] public void MultiKeyActivationDeletionNeverRotatesProviders() { using var f = new TestFolder(); var store = new SecretStore(f.Path); store.Add(Provider.Groq,"test-first-secret","First"); var first = store.ActiveId(Provider.Groq)!; store.Add(Provider.Groq,"test-second-secret","Second"); store.Activate(Provider.Groq,first); Assert.Equal("test-first-secret",store.Read(Provider.Groq)); store.Delete(Provider.Groq,first); Assert.Equal("test-second-secret",store.Read(Provider.Groq)); store.Clear(); Assert.Null(new SecretStore(f.Path).Read(Provider.Groq)); }
 [Fact] public void InvalidKeyDoesNotReplaceSavedKey() { using var f = new TestFolder(); var store = new SecretStore(f.Path); store.Add(Provider.Groq,"valid-local-fixture","one"); Assert.Throws<ArgumentException>(() => store.Add(Provider.Groq,"bad key","two")); Assert.Single(store.List(Provider.Groq)); Assert.Equal("valid-local-fixture",store.Read(Provider.Groq)); }
 [Fact] public void SettingsRoundTripAndResetPreserveOnboardingConsent() { using var f = new TestFolder(); var store = new SettingsStore(f.Path); store.Value.OnboardingComplete = true; store.Value.InjectionConsent = true; store.Value.Provider = Provider.OpenAI; store.Value.PrivateMode = true; store.Save(); var read = new SettingsStore(f.Path); Assert.True(read.Value.PrivateMode); read.Reset(); Assert.True(read.Value.OnboardingComplete); Assert.True(read.Value.InjectionConsent); Assert.False(read.Value.PrivateMode); Assert.Equal(Provider.Groq,read.Value.Provider); read.Reset(true); Assert.False(read.Value.InjectionConsent); }
 [Fact] public void MalformedSettingsPreservedForRecovery() { using var f = new TestFolder(); File.WriteAllText(System.IO.Path.Combine(f.Path,"settings.json"),"{corrupt"); var store = new SettingsStore(f.Path); Assert.Equal(Provider.Groq,store.Value.Provider); Assert.Single(Directory.GetFiles(f.Path,"settings.json.invalid-*")); }
 [Fact] public void HistoryRetentionAndPrivateMode() { using var f = new TestFolder(); var h = new HistoryStore(f.Path); var s = new QuillSettings(); h.Add("old","app",1000,"SUCCESS","Groq",s,DateTimeOffset.UtcNow.AddHours(-2)); h.Add("new","app",1000,"SUCCESS","Groq",s); s.PrivateMode = true; h.Add("private","app",1000,"SUCCESS","Groq",s); var entries = h.List(s); Assert.Single(entries); Assert.Equal("new",entries[0].Text); Assert.DoesNotContain("private",File.ReadAllText(System.IO.Path.Combine(f.Path,"history.sqlite3"))); h.Delete(entries[0].Id); Assert.Empty(h.List(s)); }
 [Fact] public void HistoryCountCapAndSecureDeletion() { using var f = new TestFolder(); var h = new HistoryStore(f.Path); var s = new QuillSettings { HistoryRetentionMinutes = 0 }; for (var i = 0; i < 1005; i++) h.Add("fixture-" + i,"app",1000,"SUCCESS","Groq",s); Assert.Equal(1000,h.List(s).Count); h.Clear(); Assert.Empty(h.List(s)); Assert.DoesNotContain("fixture-",File.ReadAllText(System.IO.Path.Combine(f.Path,"history.sqlite3"))); }
 [Fact] public void HistorySqlParametersPreserveQuotesAndUnicode() { using var f = new TestFolder(); var h = new HistoryStore(f.Path); var s = new QuillSettings(); var text = "O'Brien'); DROP TABLE transcripts; — नमस्ते 🌙"; h.Add(text,"unknown",1500,"FALLBACK_PASTE","Custom",s); Assert.Equal(text,h.List(s)[0].Text); }
}
